import gurobipy
from gurobipy import GRB

def solve_problem():
    tables = CSVQA_DATA.get('tables', [])
    table = next((t for t in tables if t.get('table_id') == 'file_0_view_0'), None)
    if table is None:
        raise ValueError("Required table 'file_0_view_0' not found in CSVQA_DATA")
    products = []
    revenue = {}
    demand = {}
    inventory = {}
    for record in table.get('records', []):
        values = record.get('values', {})
        prod = values.get('Product Name')
        if prod is None:
            raise ValueError(f"Missing 'Product Name' in record {record.get('data_row_number')}")
        rev = values.get('Revenue')
        dem = values.get('Demand')
        inv = values.get('Initial Inventory')
        if rev is None or dem is None or inv is None:
            raise ValueError(f'Missing parameter for product {prod}')
        try:
            rev_val = float(rev)
            dem_val = int(dem)
            inv_val = int(inv)
        except ValueError as e:
            raise ValueError(f'Invalid numeric value for product {prod}: {e}')
        products.append(prod)
        revenue[prod] = rev_val
        demand[prod] = dem_val
        inventory[prod] = inv_val
    for prod in products:
        if prod not in revenue or prod not in demand or prod not in inventory:
            raise ValueError(f'Missing parameter for product {prod}')
    m = gurobipy.Model('max_revenue')
    m.setParam('MIPGap', 1e-06)
    x = m.addVars(products, lb=0, vtype=GRB.INTEGER, name='')
    m.setObjective(gurobipy.quicksum((revenue[p] * x[p] for p in products)), GRB.MAXIMIZE)
    for p in products:
        m.addConstr(x[p] <= inventory[p], name=f'inv_cap_{p}')
        m.addConstr(x[p] <= demand[p], name=f'demand_cap_{p}')
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print(f'ObjVal: {m.ObjVal}')
        for var in m.getVars():
            print(f'{var.VarName}: {var.X}')
    else:
        print(f'Solver status: {m.Status}')
    return m
m = solve_problem()
